	(2, 'Giày đá bóng Nike Mercurial Vapor',    'đôi', 'Giày đá bóng sân cỏ nhân tạo, đế TF bám sân tốt, thân giày ôm chân',         'hien'),
	(2, 'Giày cầu lông Yonex Power Cushion 65Z','đôi', 'Giày cầu lông đệm êm, hỗ trợ di chuyển nhanh và giảm chấn',                  'hien'),
	(2, 'Giày chạy bộ Adidas Ultraboost Light', 'đôi', 'Giày chạy bộ đệm Boost nhẹ, hoàn trả năng lượng tốt',                        'hien'),
	(2, 'Giày tập gym Nike Metcon',             'đôi', 'Giày tập luyện đế phẳng, ổn định khi nâng tạ và tập cường độ cao',            'hien'),
	(3, 'Vợt cầu lông Yonex Nanoflare 700',     'cây', 'Vợt thiên tốc độ, đầu nhẹ, phù hợp lối chơi phản tạt nhanh',                  'hien'),
	(3, 'Vợt cầu lông Lining Axforce 80',       'cây', 'Vợt thiên công, khung cứng, cho cú đập mạnh',                                 'hien'),
	(3, 'Vợt cầu lông Victor Auraspeed 90S',    'cây', 'Vợt cân bằng, thân vợt linh hoạt, dễ kiểm soát cầu',                          'hien'),
	(1, 'Quần short thể thao nam Dri-Fit',      'cái', 'Quần short chạy bộ, tập gym, vải nhanh khô, lưng thun có dây rút',            'hien'),
	(1, 'Quần legging nữ tập gym',              'cái', 'Legging co giãn 4 chiều, lưng cao, ôm vừa vặn khi tập yoga/gym',              'hien'),
	(1, 'Quần jogger thể thao',                 'cái', 'Quần dài ống bo gấu, chất nỉ mỏng thoáng, mặc tập luyện hoặc đi chơi',        'hien'),
	(1, 'Quần short cầu lông Yonex',            'cái', 'Quần short cầu lông co giãn, thấm hút mồ hôi tốt',                            'hien'),
	(1, 'Áo thun cầu lông Yonex nam',           'cái', 'Áo thi đấu cầu lông cổ tròn, vải mè thoáng khí',                              'hien'),
	(1, 'Áo polo thể thao Adidas',              'cái', 'Áo polo vải thun lạnh, phù hợp tennis, golf và mặc hằng ngày',                'hien'),
	(1, 'Áo bra thể thao nữ',                   'cái', 'Áo bra nâng đỡ vừa, mút tháo rời, dùng cho yoga và gym',                      'hien'),
	(1, 'Áo khoác gió thể thao',                'cái', 'Áo khoác nhẹ chống gió, chống nước nhẹ, có thể gấp gọn',                      'hien'),
	(4, 'Ống cầu lông Yonex AS-50',             'ống', 'Ống 12 quả cầu lông lông vịt, độ bay ổn định, dùng thi đấu',                  'hien'),
	(4, 'Bóng đá Adidas',                       'quả', 'Bóng đá khâu máy, độ nảy tốt, bền trên sân cỏ nhân tạo',                      'hien'),
	(4, 'Dây nhảy tốc độ',                      'cái', 'Dây nhảy cáp thép bọc nhựa, tay cầm chống trượt, chỉnh được độ dài',          'hien'),
	(4, 'Tạ tay cao su',                        'đôi', 'Tạ tay bọc cao su chống trượt, dùng tập tại nhà',                             'hien'),
	(4, 'Thảm tập yoga TPE',                    'tấm', 'Thảm yoga chống trượt hai mặt, dày 6mm, kèm dây đeo',                         'hien'),
	(4, 'Con lăn foam massage',                 'cái', 'Con lăn giãn cơ, giảm mỏi sau tập luyện',                                     'hien'),
	(1, 'Áo thun thể thao nữ Nike Dri-FIT',     'cái', 'Áo thun nữ thấm hút mồ hôi, form suông nhẹ, dùng tập gym và chạy bộ', 'hien'),
	(1, 'Áo tank top gym nam',                  'cái', 'Áo ba lỗ tập gym, vải co giãn thoáng khí', 'hien'),
	(1, 'Áo hoodie thể thao nỉ',                'cái', 'Áo hoodie nỉ mỏng, có mũ và túi trước, giữ ấm khi tập ngoài trời', 'hien'),
	(1, 'Áo thun chạy bộ Adidas Own The Run',   'cái', 'Áo chạy bộ nhẹ, có chi tiết phản quang cho chạy buổi tối', 'hien'),
	(1, 'Áo đá bóng Adidas Tiro',               'cái', 'Áo đá bóng vải lưới thoáng, cổ tròn, co giãn tốt', 'hien'),
	(1, 'Quần short bóng đá Nike',              'cái', 'Quần short đá bóng nhẹ, lưng thun có dây rút', 'hien'),
	(1, 'Quần dài thể thao Adidas 3 sọc',       'cái', 'Quần dài ống đứng, 3 sọc bên hông, có túi khóa kéo', 'hien'),
	(1, 'Quần legging nam giữ nhiệt',           'cái', 'Quần bó giữ nhiệt mặc lót khi chạy bộ, đá bóng mùa lạnh', 'hien'),
