	(1, 'Bộ đồ thể thao nỉ nam',                'bộ', 'Bộ áo và quần nỉ thể thao, dùng tập luyện và mặc hằng ngày', 'hien'),
	(2, 'Giày chạy bộ Asics Gel-Kayano 30',     'đôi', 'Giày chạy bộ ổn định, đệm gel êm, phù hợp người chạy đường dài', 'hien'),
