UPDATE CTKM c
JOIN (SELECT ma_ctkm, COUNT(*) AS n FROM LUOT_SU_DUNG_KHUYEN_MAI GROUP BY ma_ctkm) l ON l.ma_ctkm = c.ma_ctkm
SET c.so_luot_da_dung = l.n
WHERE c.ma_ctkm > 0;

